DELIMITER $$
CREATE TRIGGER grade_gate BEFORE INSERT ON sc FOR EACH ROW
BEGIN
 IF NEW.Grade<60 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='分数低于登记下限'; END IF;
END$$
DELIMITER ;

DELIMITER $$
CREATE TRIGGER grade_audit_update AFTER UPDATE ON sc FOR EACH ROW
BEGIN
 IF NOT (OLD.Grade <=> NEW.Grade) THEN INSERT INTO grade_audit VALUES (NEW.Sno,NEW.Cno,OLD.Grade,NEW.Grade); END IF;
END$$
DELIMITER ;
